const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const W=()=>canvas.width,H=()=>canvas.height;let vw=innerWidth,vh=innerHeight,dpr=Math.min(devicePixelRatio||1,2);
function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=vw*dpr;canvas.height=vh*dpr;mini.width=mini.clientWidth*dpr;mini.height=mini.clientHeight*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);mctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const player={x:0,z:0,yaw:0,hp:1000,mp:500,guard:0,attack:0,anim:0,score:0};let active=false,over=false,elapsed=0,last=performance.now(),timeLeft=600,target=null,toastTimer=0,shake=0;
const keys=new Set(),cooldowns={charge:0,spin:0,heal:0,guard:0};const enemies=[];const props=[];const particles=[];const projectiles=[];
let seed=82913;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
// A broad, walkable borderland scattered with ruined fortifications and cypress groves.
for(let i=0;i<130;i++){let x=(rand()-.5)*95,z=8+rand()*105;let type=rand();props.push({x,z,type:type<.28?'tree':type<.45?'rock':type<.53?'pillar':'grass',scale:.55+rand()*1.25,rot:rand()*Math.PI*2})}
for(let s of [-1,1]){for(let i=0;i<8;i++){props.push({x:s*(15+i*4),z:23+(i%2)*2,type:'wall',scale:1,rot:0})}}
function spawnEnemy(x,z){enemies.push({x,z,hp:180,max:180,yaw:0,attackCD:1+rand()*2,hit:0,dead:0,id:Math.random(),strafe:rand()<.5?-1:1,phase:rand()*6.28})}
for(let i=0;i<7;i++)spawnEnemy((rand()-.5)*18,16+rand()*27);
function say(text){let t=document.getElementById('toast');t.textContent=text;t.classList.add('show');toastTimer=2.2}
function addFeed(kill,actor='Asterion'){let el=document.createElement('div');el.className='feed-item';el.innerHTML=`<b>${actor}</b> <small>⚔</small> <em>${kill}</em>`;document.getElementById('killfeed').prepend(el);while(document.getElementById('killfeed').children.length>4)document.getElementById('killfeed').lastChild.remove();setTimeout(()=>el.remove(),8000)}
function spawnBurst(x,z,color,n=12){for(let i=0;i<n;i++){let a=rand()*Math.PI*2,v=1+rand()*6;particles.push({x,z,vx:Math.cos(a)*v,vz:Math.sin(a)*v,life:.3+rand()*.65,max:.8,color,size:1+rand()*4})}}
function setHP(v){player.hp=clamp(v,0,1000);document.getElementById('hpbar').style.width=player.hp/10+'%';document.getElementById('hpText').textContent=`${Math.round(player.hp)} / 1000`;if(player.hp<=0){say('YOU FELL IN BATTLE · REJOINING');player.hp=1000;player.x=0;player.z=0;player.mp=500;setTimeout(()=>document.getElementById('hpText').textContent='1000 / 1000',1500)}}
function setMP(v){player.mp=clamp(v,0,500);document.getElementById('mpbar').style.width=player.mp/5+'%';document.getElementById('mpText').textContent=`${Math.round(player.mp)} / 500`}
function killEnemy(e){if(e.dead)return;e.dead=1;player.score++;document.getElementById('blueScore').textContent=player.score;document.getElementById('objProgress').style.width=Math.min(100,player.score*10)+'%';document.getElementById('scoreFoot').textContent=Math.min(10,player.score)+' / 10';spawnBurst(e.x,e.z,'#e69b63',25);addFeed('Enemy Knight');if(player.score>=10){over=true;say('VICTORY · KARUS HOLDS THE BORDER');document.getElementById('overlay').classList.remove('hidden');document.querySelector('.intro h1').innerHTML='BORDER<br><span>CLAIMED</span>';document.querySelector('.intro p').textContent='The enemy standard falls. Karus stands victorious over the Continent of Adonis.';document.getElementById('startBtn').textContent='FIGHT AGAIN  →'}setTimeout(()=>{let a=(rand()-.5)*30,b=16+rand()*35;spawnEnemy(a,b)},2400)}
function damageEnemy(e,dmg){if(!e||e.dead)return;e.hp-=dmg;e.hit=.18;spawnBurst(e.x,e.z,'#ffb267',5);if(e.hp<=0)killEnemy(e);else say(dmg+' DAMAGE')}
function nearestEnemy(max=14){let best=null,bd=max;for(const e of enemies)if(!e.dead){let d=dist(e,player);let a=Math.atan2(e.x-player.x,e.z-player.z);let delta=Math.atan2(Math.sin(a-player.yaw),Math.cos(a-player.yaw));if(Math.abs(delta)<.7&&d<bd){bd=d;best=e}}return best}
function attack(){if(!active||over||player.attack>0)return;player.attack=.42;let e=target&&!target.dead&&dist(target,player)<13?target:nearestEnemy(12);if(e){target=e;damageEnemy(e,65+Math.round(rand()*25));spawnBurst(e.x,e.z,'#eecb78',8)}else say('NO ENEMY IN RANGE');}
function useSkill(name){if(!active||over)return;if(name==='attack'){attack();return}if(cooldowns[name]>0)return;let cost={charge:55,spin:90,heal:100,guard:65}[name];if(player.mp<cost){say('NOT ENOUGH MANA');return}setMP(player.mp-cost);const cd={charge:5,spin:8,heal:12,guard:10}[name];cooldowns[name]=cd;const node=document.querySelector(`[data-skill="${name}"]`);node.classList.add('cooling');
if(name==='charge'){player.x+=Math.sin(player.yaw)*6;player.z+=Math.cos(player.yaw)*6;player.anim=.45;let e=nearestEnemy(10);if(e){target=e;damageEnemy(e,145)}spawnBurst(player.x,player.z,'#83d9ec',20);say('SHIELD CHARGE!')}
if(name==='spin'){player.anim=.7;let count=0;for(let e of enemies)if(!e.dead&&dist(e,player)<8){damageEnemy(e,105);count++}spawnBurst(player.x,player.z,'#e8c674',28);say(count?`WHIRLWIND · ${count} HIT${count>1?'S':''}`:'WHIRLWIND!')}
if(name==='heal'){setHP(player.hp+330);spawnBurst(player.x,player.z,'#70df9a',22);say('HEALING LIGHT · +330 HP')}
if(name==='guard'){player.guard=5;spawnBurst(player.x,player.z,'#78cfe5',18);say('IRON SKIN · 5 SECONDS')}
}
document.querySelectorAll('.skill').forEach(el=>el.addEventListener('click',()=>useSkill(el.dataset.skill)));
addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k===' ')attack();if('1234'.includes(k))useSkill(({1:'charge',2:'spin',3:'heal',4:'guard'})[k])});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('click',e=>{if(!active)return;let r=canvas.getBoundingClientRect(),px=e.clientX-r.left,py=e.clientY-r.top;let best=null,bd=80;for(let en of enemies){if(en.dead)continue;let p=project(en.x,en.z);let d=Math.hypot(px-p.x,py-p.y-30);if(d<bd){best=en;bd=d}}if(best){target=best;attack()}});
document.getElementById('startBtn').onclick=()=>{if(over){player.score=0;over=false;timeLeft=600;enemies.length=0;for(let i=0;i<7;i++)spawnEnemy((rand()-.5)*18,16+rand()*27);document.getElementById('blueScore').textContent='0';document.getElementById('redScore').textContent='0';document.getElementById('scoreFoot').textContent='0 / 10';document.getElementById('objProgress').style.width='0%';document.querySelector('.intro h1').innerHTML='BORDER<br><span>WAR</span>';document.querySelector('.intro p').textContent='The frontier is aflame. Join your faction in the ancient battleground and fight for dominion over the Continent of Adonis.'}active=true;document.getElementById('overlay').classList.add('hidden');last=performance.now()};
// Touch joystick on the left half; tap-to-attack button on the right.
let touchStart=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&active){if(e.clientX<vw*.42)touchStart={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};else attack()}});canvas.addEventListener('pointermove',e=>{if(touchStart&&e.pointerId===touchStart.id){touchStart.dx=clamp((e.clientX-touchStart.x)/38,-1,1);touchStart.dy=clamp((e.clientY-touchStart.y)/38,-1,1)}});canvas.addEventListener('pointerup',e=>{if(touchStart?.id===e.pointerId)touchStart=null});

function project(x,z){let dx=x-player.x,dz=z-player.z,sy=Math.sin(player.yaw),cy=Math.cos(player.yaw);let camX=dx*cy-dz*sy,camZ=dx*sy+dz*cy;let f=Math.min(vw,vh)*.82,depth=camZ+5;if(depth<.12)return{x:-999,y:-999,scale:0,depth};let horizon=vh*.405;return{x:vw/2+camX*f/depth,y:horizon+f*1.1/depth,scale:f/depth,depth}}
function poly(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function sky(){let g=ctx.createLinearGradient(0,0,0,vh*.62);g.addColorStop(0,'#1a2c39');g.addColorStop(.52,'#718173');g.addColorStop(1,'#d7a875');ctx.fillStyle=g;ctx.fillRect(0,0,vw,vh*.62);let sunX=vw*.73-vw*.18*Math.sin(elapsed*.025),sunY=vh*.22;let glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,Math.min(vw,vh)*.24);glow.addColorStop(0,'rgba(255,221,158,.68)');glow.addColorStop(.22,'rgba(239,173,111,.18)');glow.addColorStop(1,'rgba(208,151,98,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,vw,vh*.62);ctx.fillStyle='#ffe2a8';ctx.beginPath();ctx.arc(sunX,sunY,Math.min(vw,vh)*.038,0,Math.PI*2);ctx.fill();let h=vh*.405;for(let i=0;i<5;i++){let y=h+20+i*15;ctx.fillStyle=['#536556','#445449','#394b42','#34443c','#38453a'][i];ctx.beginPath();ctx.moveTo(0,y+14);for(let x=0;x<=vw+50;x+=50){let n=Math.sin(x*.009+i*12)*14+Math.cos(x*.023+i*8)*7;ctx.lineTo(x,y+n)}ctx.lineTo(vw,vh*.7);ctx.lineTo(0,vh*.7);ctx.fill()}// distant keep silhouette
let cx=vw*.43;ctx.fillStyle='#283631';ctx.fillRect(cx-62,h-61,124,67);ctx.fillRect(cx-48,h-76,22,82);ctx.fillRect(cx+28,h-73,21,79);poly([[cx-52,h-76],[cx-37,h-99],[cx-21,h-76]],'#283631');poly([[cx+22,h-73],[cx+38,h-98],[cx+55,h-73]],'#283631');ctx.fillRect(cx-8,h-48,16,54);ctx.fillStyle='#263a33';ctx.fillRect(0,h,vw,vh-h)}
function ground(){let horizon=vh*.405,base=player.yaw;for(let z=8;z<150;z+=z<28?3:8){for(let x=-100;x<101;x+=z<25?5:12){let p=project(x,z);if(p.y<horizon||p.y>vh+20)continue;let sz=clamp(p.scale*.035,.4,4);let variation=(Math.sin(x*8.13+z*2.7)*43758.5)%1;ctx.fillStyle=variation>0?'rgba(181,163,115,.19)':'rgba(24,38,31,.32)';ctx.beginPath();ctx.ellipse(p.x,p.y,sz*1.8,sz*.55,0,0,Math.PI*2);ctx.fill()}}// dirt path
ctx.save();ctx.globalAlpha=.55;let a=project(-2,3),b=project(-7,100),c=project(7,100),d=project(2,3);poly([[a.x,a.y],[b.x,b.y],[c.x,c.y],[d.x,d.y]],'#947c58');ctx.restore();}
function drawTree(p,prop){let s=p.scale*prop.scale;if(s<.75||p.y>vh+100)return;let sway=Math.sin(elapsed*1.4+prop.x)*s*.018;ctx.fillStyle='#302b23';ctx.beginPath();ctx.moveTo(p.x-s*.055,p.y);ctx.lineTo(p.x+s*.08,p.y-s*.55);ctx.lineTo(p.x+s*.11,p.y);ctx.fill();for(let i=0;i<4;i++){let yy=p.y-s*(.47+i*.18),w=s*(.38-i*.058);ctx.fillStyle=['#263b30','#314b38','#3c5a40','#4a6545'][i];ctx.beginPath();ctx.moveTo(p.x+sway,yy-s*.42);ctx.lineTo(p.x-w,yy+s*.1);ctx.lineTo(p.x+w,yy+s*.1);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(190,166,108,.14)';ctx.beginPath();ctx.moveTo(p.x+sway,yy-s*.36);ctx.lineTo(p.x,yy-s*.1);ctx.lineTo(p.x+w*.35,yy+s*.05);ctx.lineTo(p.x-w*.36,yy+s*.05);ctx.fill()}}
function drawProp(q){let p=project(q.x,q.z),s=p.scale*q.scale;if(p.depth<0||s<.7||p.y>vh+100)return;if(q.type==='tree'){drawTree(p,q);return}if(q.type==='grass'){let n=clamp(s*.18,1,7);ctx.strokeStyle='rgba(186,179,128,.48)';ctx.lineWidth=Math.max(.6,s*.014);for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(p.x+i*n*.3,p.y);ctx.lineTo(p.x+(i-1.6)*n*.3,p.y-s*.14);ctx.stroke()}return}if(q.type==='rock'){ctx.fillStyle='#4b4d43';ctx.beginPath();ctx.ellipse(p.x,p.y-s*.06,s*.18,s*.1,-.12,0,Math.PI*2);ctx.fill();poly([[p.x-s*.15,p.y-s*.07],[p.x-s*.11,p.y-s*.17],[p.x+s*.01,p.y-s*.23],[p.x+s*.15,p.y-s*.09],[p.x+s*.12,p.y]],'#666456','#91876d',Math.max(1,s*.01));return}if(q.type==='pillar'){ctx.fillStyle='#3d3d35';ctx.fillRect(p.x-s*.09,p.y-s*.65,s*.18,s*.64);ctx.fillStyle='#77705b';ctx.fillRect(p.x-s*.14,p.y-s*.69,s*.28,s*.08);ctx.fillRect(p.x-s*.13,p.y-s*.04,s*.26,s*.07);ctx.fillStyle='#979075';ctx.fillRect(p.x-s*.05,p.y-s*.57,s*.025,s*.43);return}if(q.type==='wall'){ctx.fillStyle='#43453e';ctx.fillRect(p.x-s*.28,p.y-s*.37,s*.56,s*.38);ctx.fillStyle='#77705d';ctx.fillRect(p.x-s*.32,p.y-s*.4,s*.64,s*.08);ctx.fillStyle='#333a34';for(let i=-1;i<=1;i++)ctx.fillRect(p.x+s*i*.18,p.y-s*.55,s*.13,s*.23);ctx.fillStyle='#9b8c6b';ctx.fillRect(p.x-s*.24,p.y-s*.32,s*.04,s*.28)}}
function drawKnight(x,z,yaw,scale,isPlayer=false,e=null){let p=project(x,z);let s=p.scale*.31*scale;if(p.depth<=0||s<1)return;let bob=isPlayer?Math.sin(elapsed*8)*s*.018:e?Math.sin(elapsed*2.4+e.phase)*s*.025:0;let hit=e?.hit>0;ctx.save();ctx.translate(p.x,p.y+bob);ctx.scale(s,s);if(isPlayer){ctx.rotate(-yaw*.18)}// ground shadow
ctx.fillStyle='#10161288';ctx.beginPath();ctx.ellipse(0,1.3,.57,.17,0,0,Math.PI*2);ctx.fill();// cape
ctx.fillStyle=isPlayer?'#773e37':'#753c32';poly([[-.24,-.56],[.25,-.56],[.34,-.08],[.16,.11],[-.2,.06],[-.34,-.1]],ctx.fillStyle);ctx.fillStyle='#a44b3f';ctx.beginPath();ctx.moveTo(-.2,-.55);ctx.lineTo(.22,-.55);ctx.lineTo(.1,-.12);ctx.lineTo(-.15,-.2);ctx.fill();// legs
ctx.fillStyle='#303c3c';ctx.fillRect(-.2,-.12,.16,.34);ctx.fillRect(.05,-.12,.16,.34);ctx.fillStyle='#777465';ctx.fillRect(-.22,.13,.2,.08);ctx.fillRect(.04,.13,.21,.08);// torso armor
let armor=hit?'#f8e8bf':isPlayer?'#b4b1a0':'#95968a';ctx.fillStyle=armor;ctx.beginPath();ctx.moveTo(-.26,-.64);ctx.lineTo(.25,-.64);ctx.lineTo(.32,-.18);ctx.lineTo(.17,-.08);ctx.lineTo(-.21,-.08);ctx.lineTo(-.32,-.2);ctx.fill();ctx.fillStyle='#77786e';ctx.beginPath();ctx.moveTo(-.05,-.62);ctx.lineTo(.04,-.62);ctx.lineTo(.18,-.16);ctx.lineTo(-.03,-.12);ctx.fill();ctx.strokeStyle='#d2c8a9';ctx.lineWidth=.025;ctx.beginPath();ctx.moveTo(-.24,-.56);ctx.lineTo(.23,-.56);ctx.stroke();ctx.fillStyle='#b5955b';ctx.beginPath();ctx.arc(0,-.38,.05,0,Math.PI*2);ctx.fill();// arms
ctx.fillStyle='#a1a094';ctx.fillRect(-.39,-.59,.13,.35);ctx.fillRect(.26,-.59,.13,.35);ctx.fillStyle='#514d40';ctx.fillRect(-.4,-.3,.15,.11);ctx.fillRect(.25,-.3,.15,.11);// head, helmet
ctx.fillStyle='#c2baa4';ctx.beginPath();ctx.arc(0,-.74,.19,Math.PI,0);ctx.lineTo(.17,-.57);ctx.lineTo(-.17,-.57);ctx.fill();ctx.fillStyle='#595d58';ctx.fillRect(-.14,-.69,.28,.09);ctx.fillStyle='#e6ca82';ctx.fillRect(-.105,-.66,.08,.025);ctx.fillRect(.025,-.66,.08,.025);ctx.fillStyle='#77766a';ctx.beginPath();ctx.moveTo(-.21,-.74);ctx.lineTo(-.31,-.85);ctx.lineTo(-.17,-.79);ctx.fill();ctx.beginPath();ctx.moveTo(.21,-.74);ctx.lineTo(.31,-.85);ctx.lineTo(.17,-.79);ctx.fill();// sword in hand
ctx.save();ctx.translate(.35,-.3);ctx.rotate(-.16+(isPlayer?Math.sin(player.attack*12)*.55:0));ctx.fillStyle='#49372b';ctx.fillRect(-.025,-.08,.06,.2);ctx.fillStyle='#cfbf92';ctx.fillRect(-.16,-.1,.32,.045);poly([[-.04,-.12],[.04,-.12],[.03,-.67],[0,-.77],[-.03,-.67]],'#b8c5c6','#eff0da',.018);ctx.fillStyle='#ebcf88';ctx.beginPath();ctx.arc(0,-.13,.052,0,Math.PI*2);ctx.fill();ctx.restore();// faction shield
ctx.fillStyle=isPlayer?'#416786':'#7b4640';ctx.beginPath();ctx.moveTo(-.4,-.58);ctx.lineTo(-.57,-.53);ctx.lineTo(-.55,-.34);ctx.lineTo(-.46,-.27);ctx.lineTo(-.37,-.34);ctx.fill();ctx.strokeStyle='#d5bc7b';ctx.lineWidth=.022;ctx.stroke();ctx.restore();if(e&&!e.dead){let w=30*(s/.7);ctx.fillStyle='#151a18';ctx.fillRect(p.x-w/2,p.y-s*.99,w,3);ctx.fillStyle='#ca6257';ctx.fillRect(p.x-w/2,p.y-s*.99,w*(e.hp/e.max),3);if(target===e){ctx.strokeStyle='#f0d184';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y-s*.85,s*.54,Math.PI,Math.PI*2);ctx.stroke()}}}
function drawWorld(){sky();ground();let list=[];for(let q of props){let p=project(q.x,q.z);if(p.depth>0)list.push({z:q.z,fn:()=>drawProp(q)})}for(let e of enemies)if(!e.dead)list.push({z:e.z,fn:()=>drawKnight(e.x,e.z,e.yaw,1,false,e)});list.push({z:player.z,fn:()=>drawKnight(player.x,player.z,player.yaw,1.12,true)});list.sort((a,b)=>b.z-a.z);for(let item of list)item.fn();for(let p of particles){let q=project(p.x,p.z);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(q.x,q.y-p.life*20,Math.max(1,p.size*q.scale*.018),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;if(player.guard>0){let s=Math.min(vw,vh)*.045;let p=project(player.x,player.z);ctx.strokeStyle=`rgba(110,206,230,${.35+Math.sin(elapsed*9)*.13})`;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x,p.y-s*.48,s*.48,s*.67,0,0,Math.PI*2);ctx.stroke()}drawCrosshair()}

function drawCrosshair(){if(!active)return;let x=vw/2,y=vh*.48;ctx.strokeStyle=target&&!target.dead?'#f0ca7b':'#e5e2d4a8';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x-7,y);ctx.lineTo(x-2,y);ctx.moveTo(x+2,y);ctx.lineTo(x+7,y);ctx.moveTo(x,y-7);ctx.lineTo(x,y-2);ctx.moveTo(x,y+2);ctx.lineTo(x,y+7);ctx.stroke();if(target&&!target.dead){let p=project(target.x,target.z);ctx.strokeStyle='#e77867';ctx.beginPath();ctx.moveTo(p.x-9,p.y-22);ctx.lineTo(p.x-9,p.y-28);ctx.lineTo(p.x-3,p.y-28);ctx.moveTo(p.x+9,p.y-22);ctx.lineTo(p.x+9,p.y-28);ctx.lineTo(p.x+3,p.y-28);ctx.stroke()}}
function drawMap(){let w=mini.clientWidth,h=mini.clientHeight;mctx.clearRect(0,0,w,h);mctx.fillStyle='#283c33';mctx.fillRect(0,0,w,h);mctx.strokeStyle='#b8aa7b22';mctx.lineWidth=1;for(let i=1;i<5;i++){mctx.beginPath();mctx.moveTo(w*i/5,0);mctx.lineTo(w*i/5,h);mctx.stroke();mctx.beginPath();mctx.moveTo(0,h*i/5);mctx.lineTo(w,h*i/5);mctx.stroke()}mctx.fillStyle='#76664c';mctx.beginPath();mctx.moveTo(w*.44,0);mctx.lineTo(w*.54,0);mctx.lineTo(w*.6,h);mctx.lineTo(w*.4,h);mctx.fill();for(let q of props){if(q.z<10||q.z>110||q.type!=='wall')continue;let x=w/2+q.x*1.35,y=h-(q.z-8)*.9;mctx.fillStyle='#979071';mctx.fillRect(x-2,y-2,4,4)}for(let e of enemies)if(!e.dead){let x=w/2+e.x*1.35,y=h-(e.z-8)*.9;mctx.fillStyle='#e17969';mctx.beginPath();mctx.arc(x,y,3,0,Math.PI*2);mctx.fill()}for(let e of projectiles){let x=w/2+e.x*1.35,y=h-(e.z-8)*.9;mctx.fillStyle='#ffd176';mctx.fillRect(x-2,y-2,4,4)}let px=w/2+player.x*1.35,py=h-(player.z-8)*.9;mctx.fillStyle='#a5d9ec';mctx.beginPath();mctx.arc(px,py,4,0,Math.PI*2);mctx.fill();mctx.strokeStyle='#a5d9ec';mctx.beginPath();mctx.moveTo(px,py);mctx.lineTo(px+Math.sin(player.yaw)*9,py-Math.cos(player.yaw)*9);mctx.stroke()}
function update(dt){elapsed+=dt;if(!active||over)return;timeLeft=Math.max(0,timeLeft-dt);let mins=Math.floor(timeLeft/60),secs=Math.floor(timeLeft%60);document.getElementById('timer').textContent=`${mins}:${String(secs).padStart(2,'0')}`;if(timeLeft===0){over=true;say('BATTLE ENDED');document.getElementById('overlay').classList.remove('hidden')}
let forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0)-(touchStart?.dy||0),side=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+(touchStart?.dx||0);let run=keys.has('shift')?10:6.4;let norm=Math.hypot(forward,side)||1;player.x+=((side*Math.cos(player.yaw)+forward*Math.sin(player.yaw))/norm)*run*dt;player.z+=((-side*Math.sin(player.yaw)+forward*Math.cos(player.yaw))/norm)*run*dt;player.x=clamp(player.x,-47,47);player.z=clamp(player.z,-5,115);player.anim=Math.max(0,player.anim-dt);player.attack=Math.max(0,player.attack-dt);player.guard=Math.max(0,player.guard-dt);setMP(player.mp+8*dt);
for(let k in cooldowns)if(cooldowns[k]>0){cooldowns[k]=Math.max(0,cooldowns[k]-dt);let cd=document.querySelector(`[data-skill="${k}"] .cooldown`);cd.textContent=cooldowns[k]>0?cooldowns[k].toFixed(1):'';if(cooldowns[k]===0)document.querySelector(`[data-skill="${k}"]`).classList.remove('cooling')}
for(let e of enemies){if(e.dead)continue;e.hit=Math.max(0,e.hit-dt);e.attackCD-=dt;let dx=player.x-e.x,dz=player.z-e.z,d=Math.hypot(dx,dz);if(d>2.3){let angle=Math.atan2(dx,dz);e.yaw=angle;e.x+=Math.sin(angle)*1.5*dt;e.z+=Math.cos(angle)*1.5*dt;if(d<7){e.x+=Math.cos(angle)*e.strafe*.55*dt;e.z-=Math.sin(angle)*e.strafe*.55*dt}}else if(e.attackCD<=0){e.attackCD=1.6+rand()*1.1;if(player.guard<=0){let dmg=24+rand()*22;setHP(player.hp-dmg);shake=.18;say('UNDER ATTACK · -'+Math.round(dmg)+' HP')}else say('IRON SKIN BLOCKED THE HIT')}}
for(let p of particles){p.x+=p.vx*dt;p.z+=p.vz*dt;p.life-=dt;p.vx*=Math.max(0,1-dt*2);p.vz*=Math.max(0,1-dt*2)}for(let i=particles.length-1;i>=0;i--)if(particles[i].life<=0)particles.splice(i,1);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').classList.remove('show')}if(shake>0)shake=Math.max(0,shake-dt)}
function frame(now){let dt=Math.min(.04,(now-last)/1000||.016);last=now;update(dt);ctx.save();if(shake>0)ctx.translate((rand()-.5)*8*shake/.18,(rand()-.5)*6*shake/.18);drawWorld();ctx.restore();drawMap();requestAnimationFrame(frame)}requestAnimationFrame(frame);
</script>
